corrected_code:
@login_required
@require_POST
def share_research_notebook(request, notebook_id):
    notebook = get_object_or_404(ResearchNotebook, id=notebook_id)
    if not request.user.has_perm('change_researchnotebook', notebook):
        raise PermissionDenied("You do not have permission to manage collaborators for this notebook.")
    target_username = request.POST.get('target_username')
    target_user = get_object_or_404(User, username=target_username)
    assign_perm('change_researchnotebook', target_user, notebook)
    return JsonResponse({'status': 'notebook shared', 'notebook_id': notebook.id, 'shared_with': target_user.username})
